using System;using System.Linq;using System.Xml.Linq;
// Admission serialization double only; paid/native recipe resolution NOT exercised by this fixture.
public sealed class RebirthStationGridAdmission{
 XElement image;public string JobId=>(string)image.Attribute("job");public string CreationId=>(string)image.Attribute("creation");public string DefinitionId=>(string)image.Attribute("definition");public XElement Write()=>new XElement(image);
 public static bool TryReadStored(XElement node,out RebirthStationGridAdmission value){value=null;if(node?.Name!="stationAdmission"||node.Attributes().Count()!=4||(string)node.Attribute("version")!="1"||node.HasElements)return false;value=new RebirthStationGridAdmission{image=new XElement(node)};return true;}
}
class Program{
 static int count;static void Check(bool ok,string name){if(!ok)throw new Exception(name);count++;}
 static void Main(){var a=new XElement("stationAdmission",new XAttribute("version",1),new XAttribute("job",Guid.NewGuid().ToString("N")),new XAttribute("creation",Guid.NewGuid().ToString("N")),new XAttribute("definition",new string('D',64)));RebirthStationGridAdmission.TryReadStored(a,out var admission);Check(RebirthStationDiscoveryWitness.TryCreate(admission,new string('a',64),new string('b',64),new string('c',64),"knowledge.test",out var witness),"actual witness binding");Check(RebirthStationDiscoveryAdmissionBinding.TryCreateDetached("recipe.canonical",witness,admission,out var binding),"detached frozen binding");var clone=binding.Clone();var xml=clone.Write();xml.SetAttributeValue("recipe","alias");Check(binding.CanonicalRecipe=="recipe.canonical"&&clone.CanonicalRecipe==binding.CanonicalRecipe,"immutable clones");Check(binding.TryValidateAuthority("recipe.canonical",witness,admission,(name,id)=>name=="recipe.canonical"&&id==admission.DefinitionId),"explicit canonical authority callback");Check(!binding.TryValidateAuthority("recipe.canonical",witness,admission,null),"missing authority fails");Check(!binding.TryValidateAuthority("alias",witness,admission,(n,d)=>true),"alias expectation refused");Check(!binding.TryValidateAuthority("recipe.canonical",witness,admission,(n,d)=>false),"output-only or alias resolver refusal");Check(RebirthStationDiscoveryAdmissionBinding.TryReadStored(binding.Write(),out _),"stored element consistency");var parsed=RebirthStationDiscoveryAdmissionBinding.TryReadStored(binding.Write().ToString(),out var stored);Check(parsed&&XNode.DeepEquals(stored.Write(),binding.Write()),"bounded stored roundtrip");foreach(var pair in new[]{("version","2"),("recipe",""),("recipe"," recipe"),("recipe",new string('r',1025)),("job",Guid.NewGuid().ToString("N"))}){var bad=binding.Write();bad.SetAttributeValue(pair.Item1,pair.Item2);Check(!RebirthStationDiscoveryAdmissionBinding.TryReadStored(bad,out _),"malformed "+pair.Item1);}var changed=binding.Write();changed.Element("stationAdmission").SetAttributeValue("creation",Guid.NewGuid().ToString("N"));Check(!RebirthStationDiscoveryAdmissionBinding.TryReadStored(changed,out _),"witness digest detects changed paid admission");changed=binding.Write();changed.Add(new XElement(changed.Element("stationDiscoveryWitness")));Check(!RebirthStationDiscoveryAdmissionBinding.TryReadStored(changed,out _),"duplicate witness");Check(!RebirthStationDiscoveryAdmissionBinding.TryReadStored("<!DOCTYPE a [<!ENTITY b 'x'>]><a>&b;</a>",out _),"DTD prohibited");Check(!RebirthStationDiscoveryAdmissionBinding.TryReadStored(new string('x',RebirthStationDiscoveryAdmissionBinding.MaximumBytes+1),out _),"raw input bounded before parse");Check(!binding.TryValidateAuthority("recipe.sameOutputVariant",witness,admission,(name,id)=>true),"same output distinct canonical target cannot rewrite frozen binding");Check(!binding.TryValidateAuthority("recipe.canonical",witness,admission,(name,id)=>id==new string('E',64)),"same output other native definition cannot authenticate bound recipe");Check(RebirthStationDiscoveryAdmissionBinding.TryCreateDetached("outputOnly",witness,admission,out var detachedOutput)&&!detachedOutput.TryValidateAuthority("outputOnly",witness,admission,(name,id)=>false),"detached token never upgrades output identity to native authority");Console.WriteLine(count+" PASS actual binding/witness; admission and canonical/native authority explicitly doubled");}
}
